fn is_prime(n: i8) -> bool {
    // Check if n is less than 2
    if n < 2 {
        return false;
    }

    // Loop through potential divisors from 2 to n - 1
    for divisor in 2..n {
        if n % divisor == 0 {
            return false; // Found a divisor, n is not prime
        }
    }

    // No divisors found, n is prime
    true
}